script:
document.querySelectorAll("[data-lns],[data-hang],#kolam,#star").forEach(el=>el.replaceChildren());

const $ = id => document.getElementById(id);
const WA = FMI.content.whatsapp || "";           /* the couple's WhatsApp in a real invitation */
const TARGET = new Date(FMI.content.date+"T"+FMI.content.time+":00+05:30").getTime();
const calm = FMI.reduceMotion || matchMedia("(prefers-reduced-motion: reduce)").matches;
const params = new URLSearchParams(FMI.search);
const preview = false;

/* guest name from ?to=Kumar-Family */
let guest = "";
try {
  guest = (params.get("to") || "").replace(/[-_+]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 40);
  guest = guest.split(" ").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
} catch (e) {}
if (guest) {
  $("dear").textContent = "Dear " + guest + ",";
  $("dear").hidden = false;
  $("r-name").value = guest;
  $("d-name").value = guest;
  document.title = "Dear " + guest + " · Imran & Afrin's Nikah";
}

/* hanging fanoos: x position, chain length, width (share of the column), sprite */
const HANG = {
  top:  [[7, "21svh", .15, 1], [22, "5svh", .1, 4], [38, "0svh", .075, 5], [63, "1svh", .075, 7], [79, "8svh", .11, 8], [93, "24svh", .15, 2]],
  note: [[12, "34%", .13, 3], [31, "12%", .11, 6], [50, "26%", .14, 1], [69, "8%", .11, 9], [88, "30%", .13, 2]]
};
document.querySelectorAll("[data-hang]").forEach(box => {
  (HANG[box.dataset.hang] || []).forEach(([x, ch, s, n], i) => {
    const el = document.createElement("div"); el.className = "fz";
    el.style.setProperty("--x", x + "%"); el.style.setProperty("--ch", ch); el.style.setProperty("--s", s);
    el.style.setProperty("--sd", (3.8 + (i % 3) * .7) + "s"); el.style.setProperty("--sdl", (-i * .9) + "s");
    el.innerHTML = '<img src="/assets/flagship/muslim/f' + n + '.webp" alt=""><i></i>';
    box.appendChild(el);
  });
});

/* stars for the night section */
let seed = 11;
const rnd = () => { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; };
function starfield(el, n, a){
  const sec = $("night"); const w = sec.offsetWidth, h = sec.offsetHeight; const out = [];
  for (let i = 0; i < n; i++) out.push(Math.round(rnd() * w) + "px " + Math.round(rnd() * h * .75) + "px 0 " + (rnd() < .2 ? "1px" : "0") + " rgba(255,248,230," + (a * (.4 + rnd() * .6)).toFixed(2) + ")");
  el.style.boxShadow = out.join(",");
}
starfield($("stars"), 90, .9); starfield($("stars2"), 40, 1);

/* the route: an eight-fold star rosette drawn as gold lines */
const STAR = (() => {
  const ns = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(ns, "svg"); svg.setAttribute("viewBox", "-116 -116 232 232");
  const f = v => v.toFixed(2), P = (r, a) => [r * Math.cos(a), r * Math.sin(a)];
  const paths = [];
  function add(d, a, b){ const p = document.createElementNS(ns, "path"); p.setAttribute("d", d); svg.appendChild(p); paths.push({ el: p, a, b }); }
  function dot(r, a, s){ const c = document.createElementNS(ns, "circle"); const [x, y] = P(r, a); c.setAttribute("cx", f(x)); c.setAttribute("cy", f(y)); c.setAttribute("r", s || "1.8"); svg.appendChild(c); }
  const poly = (pts) => "M" + pts.map(p => f(p[0]) + " " + f(p[1])).join(" L") + " Z ";
  const sq = (r, rot, cx = 0, cy = 0) => poly([0, 1, 2, 3].map(i => { const [x, y] = P(r, rot + i * Math.PI / 2); return [cx + x, cy + y]; }));
  dot(0, 0, "2.4");
  for (let i = 0; i < 8; i++) dot(104, i * Math.PI / 4);
  /* 1 · centre: an eight-point star from two squares */
  add(sq(30, 0) + sq(30, Math.PI / 4), .04, .2);
  /* 2 · octagram {8/3} */
  add(poly([0, 1, 2, 3, 4, 5, 6, 7].map(i => P(64, i * 3 * Math.PI / 4))), .22, .22);
  /* 3 · inner and outer circles */
  add("M46 0 A46 46 0 1 1 -46 0 A46 46 0 1 1 46 0 Z M98 0 A98 98 0 1 1 -98 0 A98 98 0 1 1 98 0 Z", .4, .16);
  /* 4 · eight small stars on the ring */
  let d = "";
  for (let i = 0; i < 8; i++) { const a = (i + .5) * Math.PI / 4; const [cx, cy] = P(82, a); d += sq(11, a, cx, cy) + sq(11, a + Math.PI / 4, cx, cy); }
  add(d, .52, .2);
  /* 5 · sixteen pointed arches around the edge */
  d = ""; const n = 16, R = 98;
  for (let i = 0; i < n; i++) {
    const a0 = i * 2 * Math.PI / n, a1 = (i + 1) * 2 * Math.PI / n, am = (a0 + a1) / 2;
    const [x0, y0] = P(R, a0), [x1, y1] = P(R, a1), [tx, ty] = P(R + 14, am);
    const [c0x, c0y] = P(R + 8, a0 + .06), [c1x, c1y] = P(R + 8, a1 - .06);
    d += (i ? "" : "M" + f(x0) + " " + f(y0)) + " Q" + f(c0x) + " " + f(c0y) + " " + f(tx) + " " + f(ty) + " Q" + f(c1x) + " " + f(c1y) + " " + f(x1) + " " + f(y1);
  }
  add(d, .66, .18);
  $("star").appendChild(svg);
  paths.forEach(p => { p.L = p.el.getTotalLength(); p.el.style.strokeDasharray = p.L; p.el.style.strokeDashoffset = calm ? 0 : p.L; });
  return paths;
})();

/* scroll engine: each scene gets --p from 0 to 1 */
const scenes = [...document.querySelectorAll("[data-scene]")];
const root = document.documentElement, routeScene = $("s-route"), lamp = $("big-lamp");
let ticking = false;
function update(){
  const vh = innerHeight;
  for (const s of scenes) {
    const r = s.getBoundingClientRect();
    const pinned = s.classList.contains("scene") && !calm;
    let p = pinned ? -r.top / Math.max(1, r.height - vh) : (vh - r.top) / (vh + r.height);
    p = Math.min(1, Math.max(0, p));
    s.style.setProperty("--p", p.toFixed(4));
    if (s === routeScene && !calm) STAR.forEach(k => { const t = Math.min(1, Math.max(0, (p - k.a) / k.b)); k.el.style.strokeDashoffset = (k.L * (1 - t)).toFixed(1); });
  }
  const lr = lamp.getBoundingClientRect();
  lamp.style.setProperty("--o", calm ? 1 : Math.min(1, Math.max(0, (vh * .9 - lr.top) / (vh * .45))).toFixed(3));
  const max = document.documentElement.scrollHeight - vh;
  root.style.setProperty("--gp", max > 0 ? (scrollY / max).toFixed(4) : 0);
  ticking = false;
}
addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
addEventListener("resize", update);
update();
if (calm) scenes.forEach(s => s.style.setProperty("--p", 1));

/* reveal on view */
const io = "IntersectionObserver" in window ? new IntersectionObserver(es => es.forEach(e => {
  if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
}), { threshold: .15 }) : null;
document.querySelectorAll(".rv").forEach(el => io ? io.observe(el) : el.classList.add("in"));

/* a soft chime, made in the browser */
let actx;
function chime(base, gain){
  try {
    actx = actx || new (window.AudioContext || window.webkitAudioContext)();
    if (actx.state === "suspended") actx.resume();
    const t0 = actx.currentTime + .02, out = actx.createGain(); out.gain.value = gain || .1; out.connect(actx.destination);
    [[1, 1, 2.4], [2, .4, 1.6], [3, .16, 1.1], [4.2, .07, .7]].forEach(([r, g, d]) => {
      const o = actx.createOscillator(); o.type = "sine"; o.frequency.value = base * r;
      const v = actx.createGain(); v.gain.setValueAtTime(0, t0); v.gain.linearRampToValueAtTime(g, t0 + .01); v.gain.exponentialRampToValueAtTime(.0001, t0 + d);
      o.connect(v); v.connect(out); o.start(t0); o.stop(t0 + d + .05);
    });
  } catch (e) {}
}

/* music: starts with the lantern, toggled from the corner button */
const music = $("music"), mBtn = $("music-btn");
let musicWanted = false;
function paintMusic(){ mBtn.classList.toggle("on", musicWanted); mBtn.setAttribute("aria-pressed", musicWanted); mBtn.setAttribute("aria-label", musicWanted ? "Pause music" : "Play music"); }
function setMusic(on){
  musicWanted = on;
  if (on) { music.volume = .75; const p = music.play(); if (p) p.catch(() => { musicWanted = false; paintMusic(); }); }
  else music.pause();
  paintMusic();
}
mBtn.addEventListener("click", () => setMusic(!musicWanted));
document.addEventListener("visibilitychange", () => { if (document.hidden) music.pause(); else if (musicWanted) music.play().catch(() => {}); });

/* gate */
const gate = $("gate");
$("open").addEventListener("click", () => {
  gate.classList.add("lit");
  chime(659.25, .08);
  document.body.classList.remove("locked");
  mBtn.hidden = false;
  setMusic(true);
  setTimeout(() => { gate.hidden = true; }, calm ? 300 : 2100);
});
if (preview) { gate.hidden = true; document.body.classList.remove("locked"); }

/* countdown */
const cells = {}; document.querySelectorAll("#count b").forEach(b => cells[b.dataset.u] = b);
function tick(){
  let s = Math.floor((TARGET - Date.now()) / 1000);
  if (s <= 0) { $("count").innerHTML = '<p style="grid-column:1/-1;font-size:1.4rem;font-style:italic">Imran and Afrin are married. Thank you for your duas!</p>'; return; }
  const d = Math.floor(s / 86400); s -= d * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  cells.d.textContent = d;
  cells.h.textContent = String(h).padStart(2, "0");
  cells.m.textContent = String(m).padStart(2, "0");
  cells.s.textContent = String(s).padStart(2, "0");
}
tick(); setInterval(tick, 1000);

/* make a dua, light a star: it rises from the button and settles beside the moon */
const skyLayer = $("sky-layer"), night = $("night"), moonEl = $("moon");
let lit = 0;
const STAR_SVG = '<svg viewBox="-12 -12 24 24"><use href="#star8"/></svg>';
$("dua-form").addEventListener("submit", e => {
  e.preventDefault();
  const name = $("d-name").value.trim(), text = $("d-text").value.trim();
  lit++;
  $("dua-msg").textContent = "Ameen. " + (name ? name + ", your" : "Your") + " star now shines beside the moon" + (lit > 1 ? " (" + lit + " stars)" : "") + ".";
  const wa = $("dua-wa");
  const msg = "A dua for Imran & Afrin 🌙\n\n" + (text || "May Allah bless you both and keep you together in goodness.") + (name ? "\n\n" + name : "");
  wa.href = "https://wa.me/" + WA + "?text=" + encodeURIComponent(msg); wa.hidden = false;
  chime(784, .1);
  const btn = e.submitter || $("dua-form").querySelector("button");
  const nr = night.getBoundingClientRect(), br = btn.getBoundingClientRect(), mr = moonEl.getBoundingClientRect();
  const x0 = br.left + br.width / 2 - nr.left - 17, y0 = br.top - nr.top - 30;
  const ang = rnd() * Math.PI * 2, dist = mr.width * (.55 + rnd() * .5);
  let tx = mr.left + mr.width / 2 - nr.left + Math.cos(ang) * dist - 17, ty = mr.top + mr.height / 2 - nr.top + Math.sin(ang) * dist * .7 - 17;
  tx = Math.min(nr.width - 40, Math.max(10, tx)); ty = Math.max(10, ty);
  const el = document.createElement("div"); el.className = "fly"; el.innerHTML = STAR_SVG + (name ? "<span></span>" : "");
  if (name) el.querySelector("span").textContent = name;
  skyLayer.appendChild(el);
  if (calm || !el.animate) { el.style.transform = "translate(" + tx + "px," + ty + "px) scale(.5)"; return; }
  const a = el.animate([
    { transform: "translate(" + x0 + "px," + y0 + "px) scale(.4) rotate(0deg)", opacity: 0 },
    { transform: "translate(" + x0 + "px," + (y0 - 30) + "px) scale(1.2) rotate(30deg)", opacity: 1, offset: .1 },
    { transform: "translate(" + ((x0 + tx) / 2 - 30) + "px," + ((y0 + ty) / 2) + "px) scale(1) rotate(160deg)", offset: .55 },
    { transform: "translate(" + tx + "px," + ty + "px) scale(.5) rotate(300deg)", opacity: 1 }
  ], { duration: 3400, easing: "cubic-bezier(.3,.1,.3,1)", fill: "forwards" });
  a.onfinish = () => {
    const s = document.createElement("div"); s.className = "settled"; s.innerHTML = STAR_SVG;
    s.style.left = (tx + 6) + "px"; s.style.top = (ty + 6) + "px"; s.style.animationDelay = (-rnd() * 2) + "s";
    skyLayer.appendChild(s); el.remove();
    const all = skyLayer.querySelectorAll(".settled"); if (all.length > 40) all[0].remove();
  };
});

/* calendar: Apple devices open the .ics, others get Google Calendar */
/* rsvp */
let guests = 2;
$("g-minus").addEventListener("click", () => { guests = Math.max(1, guests - 1); $("g-count").textContent = guests; });
$("g-plus").addEventListener("click", () => { guests = Math.min(15, guests + 1); $("g-count").textContent = guests; });
const form = $("rsvp-form");
form.addEventListener("change", () => {
  $("att-yes").style.display = form.querySelector("input[name=att]:checked").value === "yes" ? "grid" : "none";
});


/* share */
function toast(t){ const el = $("toast"); el.textContent = t; el.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => el.hidden = true, 2200); }
